===================================================================
--- index.html
+++ index.html
@@ -22,4 +22,42 @@
 </div></section><section class="side-card"><h2 class="side-title">Terrarium health <span id="threatLabel">peaceful</span></h2><div class="status"><div class="barrow"><span>Food stores</span><div class="bar"><i id="foodBar"></i></div></div><div class="barrow"><span>Nest safety</span><div class="bar hive"><i id="nestBar"></i></div></div><div class="barrow"><span>Threat</span><div class="bar danger"><i id="threatBar"></i></div></div></div></section><section class="side-card"><h2 class="side-title">Field notes <span>latest</span></h2><div class="event" id="event">The queen has settled in. Find crumbs, raise the brood and keep watch over the nest.</div></section></aside></div>
 <footer class="bottom"><span>🖱 Tap the glass to guide your ants · They gather food on their own</span><span class="hide-mobile"><i class="key">Space</i> pause &nbsp; <i class="key">R</i> new colony</span><button class="pill" id="restartBtn">↻ New colony</button></footer></main>
 <div class="modal" id="modal" hidden><div class="dialog"><h2 id="modalTitle">Welcome, Queen</h2><p id="modalText"></p><button id="modalBtn">Let's go!</button></div></div>
 <script>
+(()=>{'use strict';
+const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d');
+const $=s=>document.querySelector(s),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
+const W=1000,H=620,ground=245,nest={x:490,y:443};let dpr=1,scale=1,ox=0,oy=0;
+let G,ants=[],eggs=[],crumbs=[],particles=[],beetle=null,toastTimer=0,last=0,acc=0,paused=false,sound=true,daySeconds=0,toastTimerId;
+const unitDefs={nurse:{name:'Nurses',icon:'🧑‍⚕️',desc:'Tend the queen & brood'},collector:{name:'Collectors',icon:'🍃',desc:'Gather food & water'},soldier:{name:'Soldiers',icon:'⚔️',desc:'Guard the nest'},super:{name:'Super soldiers',icon:'🛡️',desc:'Heavy colony defense'},major:{name:'Majors',icon:'💪',desc:'Powerful frontline'},supermajor:{name:'Super majors',icon:'👑',desc:'Colony champions'}};
+const costs={nurse:8,collector:12,soldier:20,super:38,major:60,supermajor:90};
+function reset(){G={food:30,water:18,day:1,health:100,threat:0,won:false,lost:false,rally:null,gathered:0};ants=[];eggs=[];particles=[];beetle=null;daySeconds=0;paused=false;for(let i=0;i<5;i++)ants.push(makeAnt(i<1?'nurse':'collector'));for(let i=0;i<2;i++)ants.push(makeAnt('soldier'));for(const [x,y,t,n] of [[145,172,'food',5],[300,115,'water',4],[780,175,'food',7],[880,104,'water',3],[670,130,'food',4]])for(let j=0;j<n;j++)crumbs.push({x:x+(Math.random()-.5)*47,y:y+(Math.random()-.5)*32,type:t,amount:1});updateUI();setEvent('A fresh colony begins. Send workers to crumbs and bring food home.');}
+function makeAnt(role){return{x:nest.x+(Math.random()-.5)*55,y:nest.y+(Math.random()-.5)*35,role,phase:role==='collector'?'out':'nest',target:null,carry:false,angle:Math.random()*6.28,step:Math.random()*6.28,hp:1,busy:0};}
+function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(r.width*dpr);canvas.height=Math.floor(r.height*dpr);scale=Math.min(canvas.width/W,canvas.height/H);ox=(canvas.width-W*scale)/2;oy=(canvas.height-H*scale)/2;}
+new ResizeObserver(resize).observe(canvas);window.addEventListener('resize',resize);
+function worldPoint(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*dpr-ox,y:(e.clientY-r.top)*dpr-oy};}
+function notify(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimerId);toastTimerId=setTimeout(()=>el.classList.remove('show'),2100);}
+function setEvent(text){$('#event').innerHTML=text;}
+function buy(type){if(G.won||G.lost)return;const cost=costs[type];if(G.food<cost){notify('Not enough food stores yet!');return}if(ants.length>=60){notify('The nest is full — expand your colony first.');return}G.food-=cost;
+if(type==='nurse'){eggs.push({x:nest.x+(Math.random()-.5)*22,y:nest.y+13,age:0});eggs.push({x:nest.x+(Math.random()-.5)*22,y:nest.y+13,age:0});G.food+=2;setEvent('The queen laid fresh eggs. Nurses are keeping them warm.');}
+else{ants.push(makeAnt(type));if(type==='collector')ants.push(makeAnt(type));setEvent(`${unitDefs[type].name} joined the colony.`)}updateUI();}
+document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>buy(b.dataset.action));
+function updateUI(){if(!G)return;$('#food').textContent=Math.floor(G.food);$('#water').textContent=Math.floor(G.water);$('#eggs').textContent=eggs.length;$('#pop').textContent=`${ants.length} / 60`;$('#dayTop').textContent=G.day;$('#rosterSub').textContent=`${ants.length} ants`;$('#foodBar').style.width=`${clamp(G.food/1.5,2,100)}%`;$('#nestBar').style.width=`${G.health}%`;$('#threatBar').style.width=`${G.threat}%`;$('#threatLabel').textContent=G.threat>65?'under attack':G.threat>25?'watchful':'peaceful';$('#clock').textContent=`DAY ${G.day} · ${String(Math.floor(daySeconds/60)).padStart(2,'0')}:${String(Math.floor(daySeconds%60)).padStart(2,'0')}`;$('#season').textContent=G.day%4===0?'❄ COLD SEASON':'☀ WARM SEASON';
+const counts={};for(const a of ants)counts[a.role]=(counts[a.role]||0)+1;$('#unitList').innerHTML=Object.entries(unitDefs).map(([k,v])=>`<div class="unit"><div class="unit-icon">${v.icon}</div><div><div class="unit-name">${v.name}</div><div class="unit-desc">${v.desc}</div></div><div class="unit-count">${counts[k]||0}</div></div>`).join('');document.querySelectorAll('.action').forEach(b=>b.disabled=G.food<costs[b.dataset.action]||ants.length>=60||G.won||G.lost);}
+function rally(point){if(point.y<ground){G.rally={x:point.x,y:point.y};let near=crumbs.find(c=>Math.hypot(c.x-point.x,c.y-point.y)<55);if(near)G.rally={x:near.x,y:near.y};notify(near?'Collectors are on the way!':'Ants, explore this spot!');}else{G.rally=null;notify('Back to the nest, little ones!')}}
+canvas.addEventListener('pointerdown',e=>{const p=worldPoint(e);if(p.x<0||p.y<0||p.x>W||p.y>H)return;rally(p)});
+$('#pauseBtn').onclick=()=>togglePause();function togglePause(){paused=!paused;$('#pauseBtn').textContent=paused?'▶ Resume':'Ⅱ Pause';}
+$('#restartBtn').onclick=()=>{reset();};$('#soundBtn').onclick=()=>{sound=!sound;$('#soundBtn').textContent=sound?'♫ Sound on':'♫ Sound off';};$('#helpBtn').onclick=showHelp;
+function showHelp(){ $('#modalTitle').textContent='A tiny world, a big colony';$('#modalText').innerHTML='Tap a patch of crumbs to rally your collectors. Bring food and water home, lay brood, and recruit specialized ants. Soldiers automatically defend the nest when intruders arrive. Keep the queen safe through <b>5 days</b> to build a thriving colony!';$('#modalBtn').textContent='Got it';$('#modal').hidden=false;}
+$('#modalBtn').onclick=()=>$('#modal').hidden=true;window.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();togglePause()}if(e.key.toLowerCase()==='r')reset();if(e.key==='Escape')$('#modal').hidden=true;});
+function move(a,tx,ty,dt,speed){let dx=tx-a.x,dy=ty-a.y,d=Math.hypot(dx,dy);a.angle=Math.atan2(dy,dx);if(d>2){let step=Math.min(d,speed*dt);a.x+=dx/d*step;a.y+=dy/d*step;a.step+=dt*13;}return d;}
+function update(dt){if(paused||G.won||G.lost)return;daySeconds+=dt;if(daySeconds>=90){daySeconds-=90;G.day++;G.food+=Math.floor(ants.filter(a=>a.role==='collector').length*.7);G.water+=1;if(G.day%4===0){G.food=Math.max(0,G.food-4);G.water=Math.max(0,G.water-3);setEvent('Cold season! The colony is spending its stores to stay warm.');}if(G.day>=6){G.won=true;showEnd(true);}if(G.food<1){G.health-=7;setEvent('The colony is hungry. Gather food before the queen weakens!');}if(Math.random()<.58&&!beetle){beetle={x:Math.random()<.5?-20:W+20,y:ground-9,hp:50,max:50,dir:Math.random()<.5?1:-1};G.threat=55;setEvent('<strong>A hungry beetle is prowling above the nest!</strong> Soldiers, defend the colony!');}}
+for(const a of ants){if(a.role==='collector'){if(a.phase==='nest'){if(G.rally){a.phase='out';a.target={...G.rally}}else if(Math.random()<.012){a.phase='out';a.target=crumbs.length?crumbs[Math.floor(Math.random()*crumbs.length)]:{x:100+Math.random()*800,y:80+Math.random()*130}}}
+if(a.phase==='out'){if(!a.target){a.target={x:100+Math.random()*800,y:75+Math.random()*130}};move(a,a.target.x,a.target.y,dt,50);let c=crumbs.find(c=>Math.hypot(c.x-a.x,c.y-a.y)<12);if(c){c.amount--;a.carry=true;a.phase='home';a.target=null;if(c.amount<=0)crumbs.splice(crumbs.indexOf(c),1)}else if(Math.hypot(a.x-nest.x,a.y-nest.y)<14){a.phase='nest';a.target=null}}
+else if(a.phase==='home'){if(move(a,nest.x,nest.y,dt,56)<12){a.phase='nest';if(a.carry){a.carry=false;G.food+=2;G.gathered++;if(G.gathered%8===0)G.water++;}a.target=null;}}}
+else if(a.role==='nurse'){a.x+=(nest.x-a.x)*dt*.6;a.y+=(nest.y-a.y)*dt*.6;if(eggs.length&&Math.random()<.003){eggs[0].age+=.2}}
+else if(['soldier','super','major','supermajor'].includes(a.role)){if(beetle){let d=move(a,beetle.x,ground-16,dt,({soldier:65,super:78,major:86,supermajor:95})[a.role]);if(d<20){beetle.hp-=dt*({soldier:8,super:13,major:20,supermajor:32})[a.role];if(beetle.hp<=0){beetle=null;G.threat=0;G.food+=13;setEvent('<strong>The beetle has been driven off!</strong> The guards found a stash of crumbs.');notify('Intruder repelled! +13 food');}}}else{let tx=nest.x+(a.role==='soldier'?-30:30),ty=ground-16;move(a,tx,ty,dt,22);a.x+=Math.sin(a.step)*.12;}}
+}
+for(const egg of eggs)egg.age+=dt;if(eggs.length&&eggs[0].age>24&&ants.length<60){eggs.shift();ants.push(makeAnt('collector'));notify('A new worker ant hatched!');}
+if(beetle){beetle.x+=beetle.dir*dt*13;if(Math.random()<dt*.55)G.health=Math.max(0,G.health-dt*1.7);if(G.health<=0){G.lost=true;showEnd(false)}}
+if(G.health<=0){G.lost=true;showEnd(false)}updateUI();}
+function showEnd(win){$('#modalTitle').textContent=win?'A thriving ant kingdom!':'The nest has fallen';$('#modalText').innerHTML=win?'Your queen survived five seasons and the colony flourished. A beautiful world, built one crumb at a time.':'The queen needs a safer, better-fed colony. Gather more food, raise guards, and try again!';$('#modalBtn').textContent='Start a new colony';$('#modal').hidden=false;$('#modalBtn').onclick=()=>{$('#modal').hidden=true;reset();$('#modalBtn').onclick=()=>$('#modal').hidden=true;};}

