function showEnd(win){$('#modalTitle').textContent=win?'A thriving ant kingdom!':'The nest has fallen';$('#modalText').innerHTML=win?'Your queen survived five seasons and the colony flourished. A beautiful world, built one crumb at a time.':'The queen needs a safer, better-fed colony. Gather more food, raise guards, and try again!';$('#modalBtn').textContent='Start a new colony';$('#modal').hidden=false;$('#modalBtn').onclick=()=>{$('#modal').hidden=true;reset();$('#modalBtn').onclick=()=>$('#modal').hidden=true;};}
function rr(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function draw(){if(!canvas.width||!canvas.height)return;ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,canvas.width,canvas.height);ctx.setTransform(scale,0,0,scale,ox,oy);
// terrarium backdrop
let sky=ctx.createLinearGradient(0,0,0,ground);sky.addColorStop(0,'#83a98b');sky.addColorStop(1,'#c7c78b');ctx.fillStyle=sky;ctx.fillRect(0,0,W,ground);
// distant leafy silhouettes
for(let i=0;i<15;i++){let x=i*78-20,h=65+(i*37%85);ctx.fillStyle=i%2?'#587d5f':'#72916a';ctx.beginPath();ctx.ellipse(x,ground-14-h*.37,32,h*.65,0,0,Math.PI*2);ctx.fill();ctx.fillRect(x-4,ground-h*.28,8,h*.28)}
// sun
ctx.fillStyle='#f6d88d';ctx.beginPath();ctx.arc(846,68,31,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff0bf';ctx.beginPath();ctx.arc(838,60,24,0,Math.PI*2);ctx.fill();
// soil strata gradient
let soil=ctx.createLinearGradient(0,ground,0,H);soil.addColorStop(0,'#946345');soil.addColorStop(.38,'#774b36');soil.addColorStop(1,'#49362d');ctx.fillStyle=soil;ctx.fillRect(0,ground,W,H-ground);
// soil top texture, stones, root veins
ctx.strokeStyle='#c39862';ctx.globalAlpha=.52;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,ground+3);ctx.bezierCurveTo(180,ground-3,260,ground+8,430,ground+2);ctx.bezierCurveTo(620,ground-4,800,ground+6,W,ground);ctx.stroke();ctx.globalAlpha=1;
for(let i=0;i<115;i++){let x=(i*173+31)%W,y=ground+14+(i*97%(H-ground-20));ctx.fillStyle=i%3?'#644632':'#bd8a58';ctx.globalAlpha=i%3?.38:.5;ctx.beginPath();ctx.ellipse(x,y,1+(i%4),1+(i%3),i,0,6.3);ctx.fill()}ctx.globalAlpha=1;
// little surface grass and plants
for(let x=14;x<W;x+=33){ctx.strokeStyle=x%2?'#40654a':'#5f7848';ctx.lineWidth=2;for(let j=0;j<3;j++){ctx.beginPath();ctx.moveTo(x,ground+3);ctx.quadraticCurveTo(x-7+j*7,ground-4,x-9+j*10,ground-14-(j%2)*5);ctx.stroke()}}
// dandelion and clover
for(const [x,y] of [[85,ground-15],[421,ground-13],[948,ground-19]]){ctx.strokeStyle='#58764a';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y+15);ctx.lineTo(x,y-8);ctx.stroke();ctx.fillStyle='#e7d988';ctx.beginPath();ctx.arc(x,y-10,6,0,6.3);ctx.fill()}
// ants' tunnel network
ctx.lineCap='round';ctx.strokeStyle='#392d28';ctx.lineWidth=36;ctx.beginPath();ctx.moveTo(nest.x,ground+8);ctx.bezierCurveTo(nest.x-10,ground+45,455,ground+69,444,ground+106);ctx.bezierCurveTo(420,ground+145,443,ground+163,462,ground+194);ctx.stroke();ctx.beginPath();ctx.moveTo(487,ground+91);ctx.bezierCurveTo(545,ground+104,565,ground+128,568,ground+162);ctx.stroke();ctx.beginPath();ctx.moveTo(446,ground+129);ctx.bezierCurveTo(390,ground+145,367,ground+165,368,ground+196);ctx.stroke();
// tunnel lit interiors
ctx.strokeStyle='#c48c59';ctx.lineWidth=26;ctx.beginPath();ctx.moveTo(nest.x,ground+9);ctx.bezierCurveTo(nest.x-9,ground+45,455,ground+68,444,ground+106);ctx.bezierCurveTo(425,ground+145,443,ground+163,462,ground+192);ctx.stroke();ctx.beginPath();ctx.moveTo(488,ground+92);ctx.bezierCurveTo(540,ground+104,558,ground+128,562,ground+162);ctx.stroke();ctx.beginPath();ctx.moveTo(444,ground+129);ctx.bezierCurveTo(394,ground+145,373,ground+165,370,ground+192);ctx.stroke();
// chambers
rr(394,ground+77,101,63,22,'#bb8754','#51382c');rr(513,ground+138,109,66,23,'#b27b4d','#51382c');rr(321,ground+172,100,64,22,'#b27b4d','#51382c');rr(427,ground+183,105,66,23,'#bf8956','#51382c');
// chamber labels
ctx.font='10px Trebuchet MS';ctx.textAlign='center';ctx.fillStyle='#5e412e';ctx.fillText('BROOD CHAMBER',445,ground+91);ctx.fillText('FOOD STORES',566,ground+153);ctx.fillText('NURSERY',369,ground+188);
// egg piles
for(let i=0;i<eggs.length;i++){const e=eggs[i],ex=420+(i%5)*10,ey=ground+112+Math.floor(i/5)*8;ctx.fillStyle='#f5e8c1';ctx.beginPath();ctx.ellipse(ex,ey,5,3.5,-.35,0,6.3);ctx.fill();ctx.strokeStyle='#d5bc8e';ctx.lineWidth=.7;ctx.stroke()}
// seeds/food stored
for(let i=0;i<Math.min(14,Math.floor(G.food/4));i++){let x=542+(i%5)*12,y=ground+178+Math.floor(i/5)*8;ctx.fillStyle=i%2?'#e4be64':'#d99a45';ctx.beginPath();ctx.ellipse(x,y,4.7,3.4,.4,0,6.3);ctx.fill()}
// food & water patches on surface
for(const c of crumbs){ctx.save();ctx.translate(c.x,c.y);if(c.type==='food'){ctx.fillStyle='#e9bb55';ctx.beginPath();ctx.arc(0,0,5,0,6.3);ctx.fill();ctx.fillStyle='#fff0ac';ctx.beginPath();ctx.arc(-1.5,-1.5,1.3,0,6.3);ctx.fill()}else{ctx.fillStyle='#88c7ce';ctx.beginPath();ctx.ellipse(0,0,5,3.5,-.3,0,6.3);ctx.fill();ctx.fillStyle='#e3fbef';ctx.beginPath();ctx.arc(-1,-1,1,0,6.3);ctx.fill()}ctx.restore()}
// rally target pulse
if(G.rally){ctx.strokeStyle='#fff3aa';ctx.globalAlpha=.65;ctx.lineWidth=2;ctx.beginPath();ctx.arc(G.rally.x,G.rally.y,9+Math.sin(performance.now()/210)*3,0,6.3);ctx.stroke();ctx.globalAlpha=1}
// beetle intruder
if(beetle){ctx.save();ctx.translate(beetle.x,beetle.y);ctx.fillStyle='#1f2c24';ctx.beginPath();ctx.ellipse(0,0,18,11,0,0,6.3);ctx.fill();ctx.fillStyle='#425c37';ctx.beginPath();ctx.ellipse(-3,-2,11,8,-.25,0,6.3);ctx.fill();ctx.fillStyle='#d6a64c';ctx.beginPath();ctx.arc(12,-2,2,0,6.3);ctx.fill();ctx.strokeStyle='#273124';ctx.lineWidth=2;for(let i=-1;i<=1;i++){ctx.beginPath();ctx.moveTo(-5,i*4);ctx.lineTo(-14,i*8+3);ctx.moveTo(2,i*4);ctx.lineTo(11,i*8+3);ctx.stroke()}ctx.restore();ctx.fillStyle='#fff0d6';ctx.fillRect(beetle.x-20,beetle.y-21,40,4);ctx.fillStyle='#db6c53';ctx.fillRect(beetle.x-20,beetle.y-21,40*beetle.hp/beetle.max,4)}
// draw ant characters
for(const a of ants){ctx.save();ctx.translate(a.x,a.y+Math.sin(a.step)*.6);ctx.rotate(a.angle);let s=({nurse:1,collector:.95,soldier:1.16,super:1.3,major:1.48,supermajor:1.65})[a.role]||1;ctx.scale(s,s);
// legs
ctx.strokeStyle='#362019';ctx.lineWidth=1.7;for(let i=0;i<3;i++){let lx=-3+i*3;let swing=Math.sin(a.step+i*2)*2;ctx.beginPath();ctx.moveTo(lx,1);ctx.lineTo(lx-3,4+swing);ctx.lineTo(lx-6,5+swing);ctx.moveTo(lx,0);ctx.lineTo(lx+2,-4-swing);ctx.lineTo(lx+5,-5-swing);ctx.stroke()}
// abdomen, waist, thorax, head
ctx.fillStyle=a.role==='supermajor'?'#392016':a.role==='major'?'#452219':'#52291c';ctx.beginPath();ctx.ellipse(-6,0,5.1,4,0,0,6.3);ctx.fill();ctx.fillStyle='#a5532c';ctx.beginPath();ctx.arc(0,0,2.4,0,6.3);ctx.fill();ctx.fillStyle=a.role==='supermajor'?'#30190f':a.role==='major'?'#3b1d13':'#482219';ctx.beginPath();ctx.arc(5,0,a.role==='supermajor'?4.4:a.role==='major'?3.8:3.2,0,6.3);ctx.fill();
// antennae
ctx.strokeStyle='#44251b';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(6,-2);ctx.quadraticCurveTo(9,-7,12,-5);ctx.moveTo(6,2);ctx.quadraticCurveTo(10,6,12,4);ctx.stroke();if(a.carry){ctx.fillStyle='#e8bd54';ctx.beginPath();ctx.arc(-11,0,3.2,0,6.3);ctx.fill()}if(a.role==='super'||a.role==='major'||a.role==='supermajor'){ctx.strokeStyle='#d4a84e';ctx.lineWidth=1.3;ctx.beginPath();ctx.arc(0,0,8,-1.2,1.2);ctx.stroke()}ctx.restore()}
// glass edge and sunlight shimmer
ctx.strokeStyle='#ffffff22';ctx.lineWidth=5;ctx.strokeRect(3,3,W-6,H-6);ctx.strokeStyle='#efffe414';ctx.lineWidth=16;ctx.beginPath();ctx.moveTo(12,14);ctx.lineTo(12,H-15);ctx.stroke();
if(paused){ctx.fillStyle='#14201dbb';ctx.fillRect(0,0,W,H);ctx.fillStyle='#f4ead1';ctx.font='bold 30px Trebuchet MS';ctx.textAlign='center';ctx.fillText('COLONY PAUSED',W/2,H/2)}
}
function frame(t){const dt=Math.min(.05,(t-last)/1000||0);last=t;acc+=dt;if(acc>=.2){update(acc);acc=0}draw();requestAnimationFrame(frame)}
reset();resize();requestAnimationFrame(frame);
})();
</script></body></html>

